#!/usr/bin/env python3
"""7-model preview pipeline: MI Matrix -> Confound -> Regression -> Random-fault."""

import json
import itertools
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from pathlib import Path
from scipy import stats
from sklearn.metrics import mutual_info_score
import statsmodels.api as sm

# ── Constants ──
LOCAL_MODELS = [
    "qwen2.5-72b", "llama3.1-70b", "mistral-large",
    "qwen2.5-32b", "qwen2.5-14b", "llama3.1-8b",
]
API_MODELS = ["claude-3-haiku"]
ALL_MODELS = LOCAL_MODELS + API_MODELS
DATASETS = ["mmlu", "arc_challenge"]
ATTACKS = [
    "prompt_injection", "sycophancy", "score_manipulation",
    "verbosity_bias", "position_bias", "authority_bias",
]
EPS = 0.001

RESULTS_DIR = Path("/root/cert_manip_resist_eval/artifacts/results")
STEP2V3_CKPT = RESULTS_DIR / "_step2v3_checkpoint.json"
TAXONOMY_CKPT = RESULTS_DIR / "_taxonomy_checkpoint.json"
SCORES_DIR = RESULTS_DIR / "plan001" / "individual_scores"

CKPT_ATTACK_MAP = {
    "prompt_injection": STEP2V3_CKPT,
    "sycophancy": STEP2V3_CKPT,
    "score_manipulation": STEP2V3_CKPT,
    "verbosity_bias": TAXONOMY_CKPT,
    "position_bias": TAXONOMY_CKPT,
    "authority_bias": TAXONOMY_CKPT,
}


def _json_default(obj):
    if isinstance(obj, np.floating):
        v = float(obj)
        return None if (np.isnan(v) or np.isinf(v)) else v
    if isinstance(obj, np.integer):
        return int(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, np.bool_):
        return bool(obj)
    raise TypeError(f"Not serializable: {type(obj)}")


# ══════════════════════════════════════════════════════════════════════
# Data Loading
# ══════════════════════════════════════════════════════════════════════

def load_data():
    ckpt_cache = {}
    for path in [STEP2V3_CKPT, TAXONOMY_CKPT]:
        with open(path) as f:
            ckpt_cache[str(path)] = json.load(f)
    step2v3 = ckpt_cache[str(STEP2V3_CKPT)]
    taxonomy = ckpt_cache[str(TAXONOMY_CKPT)]

    clean = {}
    for ds in DATASETS:
        clean[ds] = {}
        for model in LOCAL_MODELS:
            if model in step2v3["clean_scores"].get(ds, {}):
                clean[ds][model] = step2v3["clean_scores"][ds][model]
        for model in API_MODELS:
            fpath = SCORES_DIR / f"{model}__{ds}__clean.json"
            if fpath.exists():
                with open(fpath) as f:
                    clean[ds][model] = json.load(f)["scores"]

    attacked = {}
    for ds in DATASETS:
        attacked[ds] = {}
        for atk in ATTACKS:
            attacked[ds][atk] = {}
            ckpt = ckpt_cache[str(CKPT_ATTACK_MAP[atk])]
            for model in LOCAL_MODELS:
                if model in ckpt["attacked_scores"].get(ds, {}).get(atk, {}):
                    attacked[ds][atk][model] = ckpt["attacked_scores"][ds][atk][model]
            for model in API_MODELS:
                fpath = SCORES_DIR / f"{model}__{ds}__{atk}.json"
                if fpath.exists():
                    with open(fpath) as f:
                        attacked[ds][atk][model] = json.load(f)["scores"]

    pairs = {ds: step2v3["pairs"][ds] for ds in DATASETS}
    return clean, attacked, pairs


# ══════════════════════════════════════════════════════════════════════
# Step 3: MI Matrix (21 pairs)
# ══════════════════════════════════════════════════════════════════════

def compute_mi_matrices(clean):
    mi_matrices = {}
    for ds in DATASETS:
        n = len(ALL_MODELS)
        mi_mat = np.zeros((n, n))
        winners = {}
        for i, model in enumerate(ALL_MODELS):
            if model in clean[ds]:
                winners[i] = [
                    s.get("winner", "tie") if isinstance(s, dict) else "tie"
                    for s in clean[ds][model]
                ]
        for i in range(n):
            for j in range(i + 1, n):
                if i in winners and j in winners:
                    mi = mutual_info_score(winners[i], winners[j])
                    mi_mat[i, j] = mi
                    mi_mat[j, i] = mi
        mi_matrices[ds] = mi_mat
    return mi_matrices


def mi_based_keff(mi_matrix, indices):
    K = len(indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i in indices:
        term = 1.0
        for j in indices:
            if i != j:
                term += np.exp(-2 * mi_matrix[i, j])
        keff += term
    return keff / K


# ══════════════════════════════════════════════════════════════════════
# ASR Computation
# ══════════════════════════════════════════════════════════════════════

def compute_individual_asr(clean_list, attacked_list, pairs):
    n = min(len(clean_list), len(attacked_list), len(pairs))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        if clean_list[i].get("winner", "tie") == gt:
            n_correct += 1
            if attacked_list[i].get("winner", "tie") != gt:
                n_flips += 1
    return n_flips / max(n_correct, 1)


def majority_vote(votes):
    counts = {"A": 0, "B": 0, "tie": 0}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    mc = max(counts.values())
    winners = [k for k, c in counts.items() if c == mc]
    if len(winners) == 1:
        return winners[0]
    for w in winners:
        if w != "tie":
            return w
    return "tie"


def compute_panel_asr(jids, clean, attacked, pairs):
    n = min(len(pairs), *(len(clean[j]) for j in jids), *(len(attacked[j]) for j in jids))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        cv = majority_vote([clean[j][i].get("winner", "tie") for j in jids])
        if cv != gt:
            continue
        n_correct += 1
        av = majority_vote([attacked[j][i].get("winner", "tie") for j in jids])
        if av != gt:
            n_flips += 1
    return n_flips / max(n_correct, 1)


def compute_all_individual_asr(clean, attacked, pairs):
    ind_asr = {}
    for ds in DATASETS:
        for atk in ATTACKS:
            for mid in ALL_MODELS:
                if mid in clean[ds] and mid in attacked[ds].get(atk, {}):
                    ind_asr[(ds, atk, mid)] = compute_individual_asr(
                        clean[ds][mid], attacked[ds][atk][mid], pairs[ds]
                    )
    return ind_asr


# ══════════════════════════════════════════════════════════════════════
# Confound Diagnosis
# ══════════════════════════════════════════════════════════════════════

def run_confound(mi_matrices, ind_asr):
    conditions = {}
    for ds in DATASETS:
        mi_mat = mi_matrices[ds]
        for atk in ATTACKS:
            cond = f"{ds}__{atk}"
            model_asrs = {
                m: ind_asr[(ds, atk, m)]
                for m in ALL_MODELS if (ds, atk, m) in ind_asr
            }
            if len(model_asrs) < 3:
                conditions[cond] = {"pearson_r": None, "verdict": "INSUFFICIENT_DATA", "n_panels": 0}
                continue

            available = [m for m in ALL_MODELS if m in model_asrs]
            keffs, eta_maxs = [], []
            for combo in itertools.combinations(available, 3):
                indices = [ALL_MODELS.index(m) for m in combo]
                keff = mi_based_keff(mi_mat, indices)
                eta_max = max(model_asrs[m] for m in combo)
                keffs.append(keff)
                eta_maxs.append(eta_max)

            keffs = np.array(keffs)
            eta_maxs = np.array(eta_maxs)

            if len(keffs) < 3 or np.std(keffs) < 1e-10 or np.std(eta_maxs) < 1e-10:
                r, p = 0.0, 1.0
            else:
                r, p = stats.pearsonr(keffs, eta_maxs)

            if r < -0.7:
                verdict = "CONFOUND_SEVERE"
            elif r <= -0.5:
                verdict = "CONFOUND_MODERATE"
            else:
                verdict = "CONFOUND_BROKEN"

            conditions[cond] = {
                "pearson_r": float(r),
                "p_value": float(p),
                "verdict": verdict,
                "n_panels": len(keffs),
                "keffs": keffs.tolist(),
                "eta_maxs": eta_maxs.tolist(),
            }
    return conditions


def plot_confound_scatter(conditions, output_path):
    valid = {k: v for k, v in conditions.items() if v.get("pearson_r") is not None}
    n = len(valid)
    if n == 0:
        return
    nrows, ncols = 3, 4
    fig, axes = plt.subplots(nrows, ncols, figsize=(20, 12), squeeze=False)

    for idx, (cond, data) in enumerate(sorted(valid.items())):
        row, col = divmod(idx, ncols)
        ax = axes[row][col]
        keffs = np.array(data["keffs"])
        eta_maxs = np.array(data["eta_maxs"])
        r = data["pearson_r"]
        verdict = data["verdict"]

        ax.scatter(keffs, eta_maxs, alpha=0.4, s=15, edgecolors="none", c="#3498db")
        if len(keffs) >= 3 and np.std(keffs) > 1e-10:
            z = np.polyfit(keffs, eta_maxs, 1)
            x_line = np.linspace(keffs.min(), keffs.max(), 50)
            ax.plot(x_line, np.polyval(z, x_line), "k--", alpha=0.4, linewidth=1)

        color = {
            "CONFOUND_SEVERE": "#e74c3c",
            "CONFOUND_MODERATE": "#e67e22",
            "CONFOUND_BROKEN": "#27ae60",
        }.get(verdict, "#333")
        ax.set_title(f"{cond}\nr={r:.3f} [{verdict}]", fontsize=9, color=color)
        ax.set_xlabel("K_eff", fontsize=8)
        ax.set_ylabel("eta_max", fontsize=8)
        ax.tick_params(labelsize=7)

    for idx in range(len(valid), nrows * ncols):
        row, col = divmod(idx, ncols)
        axes[row][col].set_visible(False)

    fig.suptitle("K_eff vs eta_max Confound (7 models, K=3, 35 panels)", fontsize=12, y=1.02)
    plt.tight_layout()
    plt.savefig(output_path, dpi=150, bbox_inches="tight")
    plt.close()


# ══════════════════════════════════════════════════════════════════════
# Step 4: Panel Regression (35 panels × 12 conditions)
# ══════════════════════════════════════════════════════════════════════

def run_ols(y_raw, keffs, eta_maxs):
    y = np.log(y_raw + EPS)
    X = np.column_stack([np.log(keffs), np.log(eta_maxs + EPS)])
    Xc = sm.add_constant(X)
    fit = sm.OLS(y, Xc).fit()
    return {
        "R2": float(fit.rsquared),
        "adj_R2": float(fit.rsquared_adj),
        "keff_beta": float(fit.params[1]),
        "keff_p": float(fit.pvalues[1]),
        "eta_max_beta": float(fit.params[2]),
        "eta_max_p": float(fit.pvalues[2]),
    }


def run_regression(mi_matrices, ind_asr, clean, attacked, pairs):
    results = {}
    for ds in DATASETS:
        mi_mat = mi_matrices[ds]
        for atk in ATTACKS:
            cond = f"{ds}__{atk}"
            available = [m for m in ALL_MODELS if (ds, atk, m) in ind_asr]
            p_asrs, p_keffs, p_etas = [], [], []

            for combo in itertools.combinations(available, 3):
                indices = [ALL_MODELS.index(m) for m in combo]
                keff = mi_based_keff(mi_mat, indices)
                eta_max = max(ind_asr[(ds, atk, m)] for m in combo)

                cs = {m: clean[ds][m] for m in combo}
                ats = {m: attacked[ds][atk][m] for m in combo}
                p_asr = compute_panel_asr(list(combo), cs, ats, pairs[ds])

                p_asrs.append(p_asr)
                p_keffs.append(keff)
                p_etas.append(eta_max)

            n_panels = len(p_asrs)
            if n_panels < 10:
                results[cond] = {"skipped": True, "n_panels": n_panels}
                continue

            p_asrs = np.array(p_asrs)
            p_keffs = np.array(p_keffs)
            p_etas = np.array(p_etas)

            if np.std(p_asrs) < 1e-10:
                results[cond] = {"skipped": True, "n_panels": n_panels, "reason": "constant_asr"}
                continue

            ols = run_ols(p_asrs, p_keffs, p_etas)
            results[cond] = {"skipped": False, "n_panels": n_panels, **ols}
    return results


# ══════════════════════════════════════════════════════════════════════
# Step 5: Random-fault Simulation (analytical)
# ══════════════════════════════════════════════════════════════════════

def analytical_rf_asr(eta):
    e1, e2, e3 = eta
    return e1 * e2 + e1 * e3 + e2 * e3 - 2.0 * e1 * e2 * e3


def run_random_fault(mi_matrices, ind_asr, clean, attacked, pairs):
    results = {}
    for ds in DATASETS:
        mi_mat = mi_matrices[ds]
        for atk in ATTACKS:
            cond = f"{ds}__{atk}"
            available = [m for m in ALL_MODELS if (ds, atk, m) in ind_asr]

            panel_keffs, panel_eta_maxs, panel_eta_all = [], [], []
            panel_adaptive_asrs = []

            for combo in itertools.combinations(available, 3):
                indices = [ALL_MODELS.index(m) for m in combo]
                keff = mi_based_keff(mi_mat, indices)
                etas = [ind_asr[(ds, atk, m)] for m in combo]

                cs = {m: clean[ds][m] for m in combo}
                ats = {m: attacked[ds][atk][m] for m in combo}
                adaptive_asr = compute_panel_asr(list(combo), cs, ats, pairs[ds])

                panel_keffs.append(keff)
                panel_eta_maxs.append(max(etas))
                panel_eta_all.append(etas)
                panel_adaptive_asrs.append(adaptive_asr)

            n_panels = len(panel_keffs)
            if n_panels < 10:
                results[cond] = {"skipped": True, "n_panels": n_panels}
                continue

            keffs = np.array(panel_keffs)
            eta_maxs = np.array(panel_eta_maxs)
            eta_all = np.array(panel_eta_all)
            adaptive_asrs = np.array(panel_adaptive_asrs)
            rf_asrs = np.array([analytical_rf_asr(e) for e in eta_all])

            if np.std(adaptive_asrs) < 1e-10:
                adaptive_ols = {"R2": 0, "keff_beta": 0, "keff_p": 1}
            else:
                adaptive_ols = run_ols(adaptive_asrs, keffs, eta_maxs)

            if np.std(rf_asrs) < 1e-10:
                rf_ols = {"R2": 0, "keff_beta": 0, "keff_p": 1}
            else:
                rf_ols = run_ols(rf_asrs, keffs, eta_maxs)

            delta_R2 = rf_ols["R2"] - adaptive_ols["R2"]
            keff_gains = bool(
                rf_ols["keff_p"] < 0.05 and rf_ols["keff_p"] < adaptive_ols.get("keff_p", 1)
            )

            results[cond] = {
                "skipped": False,
                "n_panels": n_panels,
                "adaptive_R2": adaptive_ols["R2"],
                "adaptive_keff_beta": adaptive_ols["keff_beta"],
                "adaptive_keff_p": adaptive_ols["keff_p"],
                "rf_R2": rf_ols["R2"],
                "rf_keff_beta": rf_ols["keff_beta"],
                "rf_keff_p": rf_ols["keff_p"],
                "delta_R2": float(delta_R2),
                "keff_gains_sig": keff_gains,
            }
    return results


# ══════════════════════════════════════════════════════════════════════
# Main
# ══════════════════════════════════════════════════════════════════════

def main():
    print("=" * 70)
    print("7-MODEL PREVIEW PIPELINE (6 local + claude-3-haiku)")
    print("=" * 70)

    # Load
    print("\n[1/5] Loading data...")
    clean, attacked, pairs = load_data()
    for ds in DATASETS:
        avail = [m for m in ALL_MODELS if m in clean[ds]]
        print(f"  {ds}: {len(avail)}/{len(ALL_MODELS)} models")

    # MI
    print("\n[2/5] Computing MI matrix (C(7,2)=21 pairs)...")
    mi_matrices = compute_mi_matrices(clean)
    for ds in DATASETS:
        mi = mi_matrices[ds]
        upper = mi[np.triu_indices_from(mi, k=1)]
        nz = upper[upper > 0]
        if len(nz) > 0:
            print(f"  {ds}: MI [{nz.min():.4f}, {nz.max():.4f}], mean={nz.mean():.4f}")

    # Individual ASR
    print("\n[3/5] Computing individual ASR...")
    ind_asr = compute_all_individual_asr(clean, attacked, pairs)
    print(f"  {len(ind_asr)} ASR values (expect {len(ALL_MODELS)*len(DATASETS)*len(ATTACKS)}=84)")

    # Print per-model ASR summary
    print("\n  Per-model ASR (mean across conditions):")
    for mid in ALL_MODELS:
        asrs = [ind_asr[(ds, atk, mid)] for ds in DATASETS for atk in ATTACKS if (ds, atk, mid) in ind_asr]
        if asrs:
            print(f"    {mid:<20s} mean={np.mean(asrs):.3f} min={min(asrs):.3f} max={max(asrs):.3f}")

    # Confound
    print("\n[4/5] Confound diagnosis (C(7,3)=35 panels x 12 conditions)...")
    confound = run_confound(mi_matrices, ind_asr)
    scatter_path = RESULTS_DIR / "7model_confound_scatter.png"
    plot_confound_scatter(confound, scatter_path)

    print(f"\n  {'Condition':<40} {'r':>7} {'Verdict':<20} {'Panels':>6}")
    print("  " + "-" * 75)
    for cond, data in sorted(confound.items()):
        r = data.get("pearson_r")
        v = data.get("verdict", "N/A")
        n = data.get("n_panels", 0)
        r_str = f"{r:.3f}" if r is not None else "N/A"
        print(f"  {cond:<40} {r_str:>7} {v:<20} {n:>6}")

    r_vals = [v["pearson_r"] for v in confound.values() if v.get("pearson_r") is not None]
    if r_vals:
        mean_r = np.mean(r_vals)
        n_severe = sum(1 for r in r_vals if r < -0.7)
        n_broken = sum(1 for r in r_vals if r > -0.5)
        print(f"\n  Mean r = {mean_r:.3f}")
        print(f"  Severe: {n_severe}/12, Broken: {n_broken}/12")

    # Regression
    print("\n[5a/5] Panel regression (35 panels x 12 conditions)...")
    regression = run_regression(mi_matrices, ind_asr, clean, attacked, pairs)
    valid_reg = {k: v for k, v in regression.items() if not v.get("skipped")}
    nv = len(valid_reg)
    n_keff_sig_neg = sum(
        1 for v in valid_reg.values()
        if v["keff_beta"] < 0 and v["keff_p"] < 0.05
    )
    n_eta_sig = sum(1 for v in valid_reg.values() if v["eta_max_p"] < 0.05)

    print(f"\n  K_eff sig negative: {n_keff_sig_neg}/{nv}")
    print(f"  eta_max sig:        {n_eta_sig}/{nv}")
    print(f"\n  {'Condition':<40} {'R2':>6} {'K_eff B':>9} {'K_eff p':>9} {'eta B':>9} {'eta p':>9}")
    print("  " + "-" * 85)
    for cond, d in sorted(valid_reg.items()):
        sig_k = "*" if d["keff_p"] < 0.05 else ""
        sig_e = "*" if d["eta_max_p"] < 0.05 else ""
        print(
            f"  {cond:<40} {d['R2']:>6.3f} {d['keff_beta']:>+9.4f} {d['keff_p']:>8.4f}{sig_k}"
            f" {d['eta_max_beta']:>+9.4f} {d['eta_max_p']:>8.4f}{sig_e}"
        )

    # Random-fault
    print("\n[5b/5] Random-fault (analytical, 35 panels x 12 conditions)...")
    rf_results = run_random_fault(mi_matrices, ind_asr, clean, attacked, pairs)
    valid_rf = {k: v for k, v in rf_results.items() if not v.get("skipped")}
    nvr = len(valid_rf)
    n_adapt_sig = sum(
        1 for v in valid_rf.values()
        if v["adaptive_keff_beta"] < 0 and v["adaptive_keff_p"] < 0.05
    )
    n_rf_sig = sum(
        1 for v in valid_rf.values()
        if v["rf_keff_beta"] < 0 and v["rf_keff_p"] < 0.05
    )
    n_gains = sum(1 for v in valid_rf.values() if v.get("keff_gains_sig"))
    mean_dR2 = np.mean([v["delta_R2"] for v in valid_rf.values()]) if valid_rf else 0

    print(f"\n  Adaptive K_eff sig neg: {n_adapt_sig}/{nvr}")
    print(f"  RF K_eff sig neg:       {n_rf_sig}/{nvr}")
    print(f"  K_eff gains sig:        {n_gains}/{nvr}")
    print(f"  Mean delta R2:          {mean_dR2:+.4f}")
    print(f"\n  {'Condition':<40} {'Adap R2':>8} {'RF R2':>8} {'dR2':>7} {'Adap Kp':>8} {'RF Kp':>8} {'Gain':>5}")
    print("  " + "-" * 85)
    for cond, d in sorted(valid_rf.items()):
        g = "Y" if d["keff_gains_sig"] else "N"
        print(
            f"  {cond:<40} {d['adaptive_R2']:>8.4f} {d['rf_R2']:>8.4f} "
            f"{d['delta_R2']:>+7.3f} {d['adaptive_keff_p']:>8.4f} {d['rf_keff_p']:>8.4f} {g:>5}"
        )

    # Save
    output = {
        "models": ALL_MODELS,
        "n_models": len(ALL_MODELS),
        "n_panels": 35,
        "confound": {
            k: {kk: vv for kk, vv in v.items() if kk not in ("keffs", "eta_maxs")}
            for k, v in confound.items()
        },
        "confound_summary": {
            "mean_r": float(mean_r) if r_vals else None,
            "n_severe": n_severe if r_vals else 0,
            "n_broken": n_broken if r_vals else 0,
        },
        "regression": regression,
        "regression_summary": {
            "keff_sig_negative": f"{n_keff_sig_neg}/{nv}",
            "eta_max_sig": f"{n_eta_sig}/{nv}",
        },
        "random_fault": rf_results,
        "random_fault_summary": {
            "adaptive_keff_sig_neg": f"{n_adapt_sig}/{nvr}",
            "rf_keff_sig_neg": f"{n_rf_sig}/{nvr}",
            "keff_gains_sig": f"{n_gains}/{nvr}",
            "mean_delta_R2": float(mean_dR2),
        },
    }
    output_path = RESULTS_DIR / "results_7model_preview.json"
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2, default=_json_default, ensure_ascii=False)

    print(f"\n\nResults: {output_path}")
    print(f"Scatter: {scatter_path}")
    print("=" * 70)


if __name__ == "__main__":
    main()
